 public static void Attach(MainWindow w,Application app){w.Loaded+=async (_,_)=>{try{var vm=(MainVm)w.DataContext;var fixture=System.IO.Path.Combine(AppContext.BaseDirectory,"ui-test-fixture");Directory.CreateDirectory(System.IO.Path.Combine(fixture,"Documents"));Directory.CreateDirectory(System.IO.Path.Combine(fixture,"Downloads"));File.WriteAllBytes(System.IO.Path.Combine(fixture,"Downloads","setup-demo.exe"),new byte[1048576]);File.WriteAllBytes(System.IO.Path.Combine(fixture,"Documents","report.pdf"),new byte[524288]);File.WriteAllBytes(System.IO.Path.Combine(fixture,"movie.mp4"),new byte[2097152]);Directory.CreateDirectory(System.IO.Path.Combine(fixture,"node_modules"));File.WriteAllBytes(System.IO.Path.Combine(fixture,"archive.zip"),new byte[2097152]);File.WriteAllBytes(System.IO.Path.Combine(fixture,"photo.png"),new byte[1048576]);var oldFile=System.IO.Path.Combine(fixture,"node_modules","old.bin");File.WriteAllBytes(oldFile,new byte[2097152]);File.SetLastWriteTimeUtc(oldFile,DateTime.UtcNow.AddDays(-200));vm.Root=fixture;await vm.ScanRoot();await vm.Refresh();await BrowseViewTests.Verify(w,app,vm);await HoverStyleTests.Verify(w,app);if(vm.ActiveTab!=0||vm.InvestigationRows.Count!=0||vm.InvestigationCards.Count!=0||vm.InsightCategories.Count!=0)throw new Exception("Heavy views queried before being opened");await vm.LoadInsights();if(vm.InsightCategories.Count==0||vm.InsightFolders.Count==0||w.Icon==null)throw new Exception("Insights or icon missing");var only=vm.SelectedScan!;if(HistoryChart.Measurements([only],only.Root,"Month").Length!=1||HistoryChart.Measurements([only,only with {Id="second",Date=DateTime.Parse(only.Date).AddMinutes(1).ToString("O")}],only.Root,"Scan").Length!=2)throw new Exception("History chart aggregation failed");var previousCount=vm.History.Count;vm.ViewDrive.Execute(new Entry(only.Root,0,0,"offline"));await vm.Refresh();if(vm.History.Count!=previousCount||vm.Busy)throw new Exception("View last scan triggered another scan");if(vm.SelectedScan?.Files!=6)throw new Exception("UI scan failed: "+vm.Status);var tabs=Find<TabControl>(w)!;tabs.SelectedIndex=0;await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-dark-map.png");tabs.SelectedIndex=1;await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-dark-search.png");vm.Query="*.pdf";var searchTask=vm.Refresh();if(!searchTask.IsCompleted&&(vm.Rows.Count!=0||!vm.IsSearchLoading))throw new Exception("Search shows stale rows while loading");await searchTask;if(vm.Rows.Count!=1||!vm.Rows[0].Path.EndsWith(".pdf")||vm.IsSearchLoading)throw new Exception("Wildcard UI search failed");await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-wildcard-search.png");VerifyDoubleClick(w,vm);vm.Query="";await vm.Refresh();w.ApplyTheme(true);w.Width=640;w.Height=480;await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-light-small.png");tabs.SelectedIndex=3;w.Width=1200;w.Height=800;await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-light-insights.png");w.ApplyTheme(false);Render(w,"ui-dark-insights.png");vm.Period="Month";Render(w,"ui-single-period.png");tabs.SelectedIndex=2;vm.SelectedInvestigation=vm.InvestigationPresets[4];await vm.LoadInvestigation();if(vm.InvestigationRows.Count!=2)throw new Exception("Archive/image UI preset failed");Render(w,"ui-investigate-wide.png");w.Width=640;w.Height=600;await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-investigate-compact.png");w.Width=1200;w.Height=800;vm.SelectedInvestigation=vm.InvestigationPresets[5];await vm.LoadInvestigation();if(vm.InvestigationRows.Count!=1)throw new Exception("Developer UI preset failed");Render(w,"ui-developer.png");vm.SelectedInvestigation=vm.InvestigationPresets[7];await vm.LoadInvestigation();if(vm.InvestigationRows.Any(r=>r.Kind=="file"))throw new Exception("Health label/results mismatch");vm.SelectedInvestigation=vm.InvestigationPresets[0];await vm.LoadInvestigation();if(!vm.InvestigationStatus.Contains("No earlier compatible snapshot")&&!vm.InvestigationStatus.Contains("changed items"))throw new Exception("Comparison missing baseline state failed");tabs.SelectedIndex=4;vm.Drives.Clear();vm.Drives.Add(new Entry("C:\\",536870912000,0,"drive","Fixed • Local Disk • serial 1234ABCD"));w.Width=1200;w.Height=800;await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-drives-aligned.png");tabs.SelectedIndex=0;using(var stream=new FileStream(System.IO.Path.Combine(fixture,"movie.mp4"),FileMode.Append)){stream.WriteByte(1);}await vm.ScanRoot();var newest=vm.SelectedScan!;vm.History.Clear();vm.History.Add(newest);vm.SelectedScan=newest;tabs.SelectedIndex=2;vm.SelectedInvestigation=vm.InvestigationPresets[0];await vm.LoadInvestigation();if(vm.IsInvestigationLoading)throw new Exception("Investigation progress remained active after completion");if(vm.InvestigationRows.Count==0||string.IsNullOrEmpty(vm.ComparisonContext)||vm.History.Count<2||vm.SelectedScan?.Id!=newest.Id)throw new Exception("Comparison failed to restore stale history while preserving selection");vm.History.Clear();vm.History.Add(newest);vm.SelectedScan=newest;await vm.LoadInsights();if(vm.History.Count<2||vm.SelectedScan?.Id!=newest.Id)throw new Exception("History view failed to reload saved snapshots while preserving selection");await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-comparison-reloaded.png");vm.SelectedInvestigation=vm.InvestigationPresets[6];await vm.LoadInvestigation();var view=Find<InvestigationView>(w)!;var quickButton=(Button)view.FindName("QuickCheckButton");var fullButton=(Button)view.FindName("FullCheckButton");quickButton.Command.Execute(quickButton.CommandParameter);if(vm.QuickDuplicateCheck.CanExecute(null)||vm.FullDuplicateCheck.CanExecute(null)||!vm.Stop.CanExecute(null))throw new Exception("Duplicate buttons/Stop have incorrect running state");var duplicateDeadline=DateTime.UtcNow.AddSeconds(20);while(vm.Busy&&DateTime.UtcNow<duplicateDeadline)await Task.Delay(20);if(vm.Busy||vm.InvestigationRows.Count==0||!vm.InvestigationStatus.StartsWith("Quick"))throw new Exception("Quick duplicate mode UI workflow failed");await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-duplicate-quick.png");fullButton.Command.Execute(fullButton.CommandParameter);while(vm.Busy&&DateTime.UtcNow<duplicateDeadline)await Task.Delay(20);if(vm.Busy||vm.InvestigationRows.Count==0||!vm.InvestigationStatus.StartsWith("Full"))throw new Exception("Complete duplicate mode UI workflow failed");await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-duplicate-full.png");VerifyDoubleClick(w,vm);vm.SelectedInvestigation=vm.InvestigationPresets[0];var pending=vm.LoadInvestigation();if(!pending.IsCompleted&&!vm.IsInvestigationLoading)throw new Exception("No investigation progress during pending work");tabs.SelectedIndex=0;if(vm.IsInvestigationLoading)throw new Exception("Investigation indicator remained visible after leaving tab");await pending;tabs.SelectedIndex=0;vm.MapRows.Clear();vm.MapRows.Add(new Entry("C:\\Users",300,0,"folder"));vm.MapRows.Add(new Entry("C:\\Windows",100,0,"folder"));vm.MapRows.Add(new Entry("C:\\Program Files",60,0,"folder"));vm.MapRows.Add(new Entry("C:\\ExampleData",120,0,"folder"));vm.MapRows.Add(new Entry("C:\\pagefile.sys",40,0,"file"));await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-folder-colours.png");w.ApplyTheme(true);w.Width=640;w.Height=480;await app.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Render(w,"ui-folder-colours-light-small.png");var wrongThread=false;vm.Drives.CollectionChanged+=(_,_)=>{if(!app.Dispatcher.CheckAccess())wrongThread=true;};await Task.Run(()=>vm.LoadDrives());if(wrongThread||vm.Status.Contains("Drive discovery unavailable"))throw new Exception("Drive discovery changed UI collection off dispatcher");AppIcon.ValidateShapes();var errors=System.IO.Path.Combine(Store.DefaultHome!,"errors.log");if(File.Exists(errors))throw new Exception(File.ReadAllText(errors));File.WriteAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"ui-test-result.txt"),"PASS startup, live scan workflow, MVVM data binding, dark map/search, light 640x480 layout, history chart (single period and per-scan), populated category/folder charts, app icon, view-last-scan without rescanning, comparison reload with deliberately stale in-memory history. Folder colours, background-thread drive discovery and investigation progress completion/navigation and dedicated Quick/Full duplicate buttons and wildcard search loading states and Search/Investigate double-click file reveal verified. Rendered PNGs saved.");}catch(Exception ex){File.WriteAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"ui-test-failure.txt"),ex.ToString());}finally{w.Close();app.Shutdown();}};}
 static void VerifyDoubleClick(Window w,MainVm vm){var grid=Find<DataGrid>(w)!;grid.UpdateLayout();var row=(DataGridRow?)grid.ItemContainerGenerator.ContainerFromIndex(0)??throw new Exception("No rendered file row");var entry=(Entry)row.Item;string? revealed=null;Actions.RevealTestOverride=p=>revealed=p;try{grid.RaiseEvent(new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,Environment.TickCount,System.Windows.Input.MouseButton.Left){RoutedEvent=Control.MouseDoubleClickEvent,Source=row});if(revealed!=entry.Path)throw new Exception("Double-click did not dispatch the exact file path");revealed=null;grid.RaiseEvent(new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,Environment.TickCount,System.Windows.Input.MouseButton.Left){RoutedEvent=Control.MouseDoubleClickEvent,Source=grid});if(revealed!=null)throw new Exception("Empty-grid double-click opened a stale selected file");}finally{Actions.RevealTestOverride=null;}}
 static T? Find<T>(DependencyObject o)where T:DependencyObject{if(o is T t)return t;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++){var result=Find<T>(VisualTreeHelper.GetChild(o,i));if(result!=null)return result;}return null;}
 public static void Render(Window w,string name){w.UpdateLayout();var bitmap=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(w);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var f=File.Create(System.IO.Path.Combine(AppContext.BaseDirectory,name));encoder.Save(f);}
}












